    for i, j in zip(encoded, original):
        if i not in mapping:
            mapping[i] = j
        elif mapping[i] != j:
            return "Failed"

    # Use the mapping to decode the message
    decoded = ""
    for letter in message:
        if letter in mapping:
            decoded += mapping[letter]
        else:
            return "Failed"

    return decoded

